mapper.select:
SELECT DISTINCT t.TODO_ID as todoId, t.OWNER_USER_ID as ownerUserId, t.TITLE as title, t.DESCRIPTION as description, t.PRIORITY as priority, t.DUE_DATE as dueDate, t.DUE_TIME as dueTime, t.IS_COMPLETED as isCompleted, t.COMPLETED_AT as completedAt, t.SORT_ORDER as sortOrder, t.GROUP_ID as groupId, t.CREATED_AT as createdAt, t.CREATED_BY as createdBy, t.UPDATED_AT as updatedAt, t.UPDATED_BY as updatedBy, ou.NAME as ownerUserName, g.GROUP_NAME as groupName, g.GROUP_COLOR as groupColor, CASE WHEN t.OWNER_USER_ID = #{ownerUserId} THEN FALSE ELSE TRUE END AS isGroupShared FROM TB_TODO t LEFT JOIN TB_USER ou ON t.OWNER_USER_ID = ou.USER_ID LEFT JOIN TB_GROUP g ON t.GROUP_ID = g.GROUP_ID LEFT JOIN TB_USER cu ON cu.USER_ID = #{ownerUserId} LEFT JOIN TB_USER_GROUP ug ON t.GROUP_ID = ug.GROUP_ID AND ug.USERNAME = cu.USERNAME AND ug.DELETED_AT IS NULL WHERE t.USE_YN = 'Y' AND t.DUE_DATE IS NOT NULL AND t.DUE_DATE >= #{startDate} AND t.DUE_DATE <= #{endDate} AND ( t.OWNER_USER_ID = #{ownerUserId} OR (t.GROUP_ID IS NOT NULL AND ug.USER_GROUP_ID IS NOT NULL) )
AND t.GROUP_ID = #{groupId}
ORDER BY t.DUE_DATE, t.DUE_TIME, t.PRIORITY DESC

SELECT i.ITEM_ID as itemId, i.BOARD_ID as boardId, i.CONTENT as title, i.CONTENT as content, i.STATUS as status, i.PRIORITY as priority, i.REQUEST_DATE as requestDate, i.DUE_DATE as dueDate, i.PARENT_ITEM_ID as parentItemId, i.ITEM_DEPTH as itemDepth, b.BOARD_NAME as boardName, COALESCE(i.DUE_DATE, i.REQUEST_DATE) as displayDate FROM TB_ITEM i INNER JOIN TB_BOARD b ON i.BOARD_ID = b.BOARD_ID WHERE (i.DUE_DATE IS NOT NULL OR i.REQUEST_DATE IS NOT NULL) AND COALESCE(i.DUE_DATE, i.REQUEST_DATE) >= #{startDate} AND COALESCE(i.DUE_DATE, i.REQUEST_DATE) <= #{endDate} AND i.STATUS NOT IN ('DELETED') AND b.USE_YN = 'Y' AND ( b.OWNER_USERNAME = #{username} OR EXISTS ( SELECT 1 FROM TB_BOARD_SHARE bs WHERE bs.BOARD_ID = b.BOARD_ID AND bs.USERNAME = #{username} AND bs.DELETED_AT IS NULL ) )
AND i.BOARD_ID = #{boardId}
ORDER BY COALESCE(i.DUE_DATE, i.REQUEST_DATE), i.PRIORITY DESC, i.SORT_ORDER

SELECT
    MIN(LEAST(
        COALESCE(i.REQUEST_DATE, i.DUE_DATE, DATE(i.CREATED_AT)),
        COALESCE(i.DUE_DATE, i.REQUEST_DATE, DATE(i.CREATED_AT))
    )) as minDate,
    MAX(GREATEST(
        COALESCE(i.DUE_DATE, i.REQUEST_DATE, DATE(i.CREATED_AT)),
        COALESCE(i.REQUEST_DATE, i.DUE_DATE, DATE(i.CREATED_AT))
    )) as maxDate
FROM TB_ITEM i
INNER JOIN TB_BOARD b ON i.BOARD_ID = b.BOARD_ID
WHERE i.STATUS != 'DELETED'
  AND b.USE_YN = 'Y'
  AND (
      b.OWNER_USERNAME = #{username}
      OR EXISTS (
          SELECT 1 FROM TB_BOARD_SHARE bs
          WHERE bs.BOARD_ID = b.BOARD_ID
            AND bs.USERNAME = #{username}
            AND bs.DELETED_AT IS NULL
      )
  )

  AND i.BOARD_ID = #{boardId}

SELECT ip.ITEM_ID as itemId, ip.PROPERTY_ID as propertyId, ip.VALUE_DATE as valueDate FROM TB_ITEM_PROPERTY ip WHERE ip.ITEM_ID IN
#{itemId}
AND ip.PROPERTY_ID IN (#{startDatePropertyId}, #{completionDatePropertyId}) AND ip.VALUE_DATE IS NOT NULL
